import {random,pick} from './service.js';
const koreanOrder=new Intl.Collator('ko',{numeric:false,sensitivity:'variant'});
export function splitCallNumber(value){let text=String(value).replace(/[\s-]/g,''),match=text.match(/^(\d+(?:\.\d+)?)([가-힣ㄱ-ㅎㅏ-ㅣ]*)(\d*)([가-힣ㄱ-ㅎㅏ-ㅣ]*)$/);if(!match)throw Error('청구기호 형식을 확인하세요: '+value);return {classification:Number(match[1]),author:match[2],authorNumber:match[3],suffix:match[4]}}
export function compareCallNumbers(a,b){let x=splitCallNumber(a),y=splitCallNumber(b);if(x.classification!==y.classification)return x.classification-y.classification;let author=koreanOrder.compare(x.author,y.author);if(author)return author;let size=Math.max(x.authorNumber.length,y.authorNumber.length),xn=x.authorNumber.padEnd(size,'0'),yn=y.authorNumber.padEnd(size,'0');if(xn!==yn)return xn<yn?-1:1;return koreanOrder.compare(x.suffix,y.suffix)}
export function correctInsertionSlot(books,target){return books.filter(code=>compareCallNumbers(code,target)<0).length}
export function makeShelvingPuzzle(s,category){let codes=[],base=`${category*100+8}.${Math.floor(random(s)*99)+1}`;while(codes.length<6){let author=pick(s,['가','나','다']),number=String(1+Math.floor(random(s)*990)),suffix=pick(s,['가','나','다']);let code=base+author+number+suffix;if(!codes.some(c=>compareCallNumbers(c,code)===0))codes.push(code)}let target=codes.pop();codes.sort(compareCallNumbers);return {category,books:codes,target,answer:correctInsertionSlot(codes,target),slot:null}}
export function recordShelfArrangement(s,puzzle,slot){let success=slot===puzzle.answer;s.shelfStatus[puzzle.category]=success?'clean':'failed';s.progress.shelvesCleaned=s.shelfStatus.filter(status=>status==='clean').length;s.stats.shelfArrangements++;s.stats.shelfAttempts++;if(success)s.stats.booksShelved++;return success}
export function shelfBookMissing(s,category){let status=s.shelfStatus[category];return status==='failed'||(status!=='clean'&&random(s)<.15)}
